        <b>Legend:</b>
        <span style="display:inline-block;width:12px;height:12px;background:#000;margin-right:4px;"></span>Wall
        <span style="display:inline-block;width:12px;height:12px;background:#777;margin-left:12px;margin-right:4px;"></span>Floor
        <span style="display:inline-block;width:12px;height:12px;background:#0f0;margin-left:12px;margin-right:4px;"></span>Spawn
        <span style="display:inline-block;width:12px;height:12px;background:#f00;margin-left:12px;margin-right:4px;"></span>Weapon
    `;
    legend.style.marginTop = '8px';
    container.appendChild(legend);

    document.body.appendChild(container);
    generateMap('fpsMapCanvas');
})();

Solution B: ```javascript
function generateFPSMap(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    const width = 500;
    const height = 500;
    const cellSize = 10;
    const mapWidth = width / cellSize;
    const mapHeight = height / cellSize;

    let map = [];
    for (let y = 0; y < mapHeight; y++) {
        map[y] = [];
        for (let x = 0; x < mapWidth; x++) {
            map[y][x] = 0; // 0: floor, 1: wall
        }
    }

    function createRoom(x, y, w, h) {
        for (let i = x; i < x + w; i++) {
            for (let j = y; j < y + h; j++) {
                if (i > 0 && i < mapWidth - 1 && j > 0 && j < mapHeight - 1) {
                    map[j][i] = 0;
                }
            }
        }
    }

    function createCorridor(x1, y1, x2, y2) {
        while (x1 !== x2 || y1 !== y2) {
            if (x1 < x2) x1++;
            else if (x1 > x2) x1--;
            else if (y1 < y2) y1++;
            else if (y1 > y2) y1--;

            if (x1 > 0 && x1 < mapWidth - 1 && y1 > 0 && y1 < mapHeight - 1) {
                map[y1][x1] = 0;
            }
        }
    }

    function floodFill(x, y) {
        if (x < 0 || x >= mapWidth || y < 0 || y >= mapHeight || map[y][x] === 1) return;

        map[y][x] = 2; // Mark as visited

        floodFill(x + 1, y);
        floodFill(x - 1, y);
        floodFill(x, y + 1);
        floodFill(x, y - 1);
    }

    function isReachable() {
        let reachable = false;
        for (let y = 0; y < mapHeight; y++) {
            for (let x = 0; x < mapWidth; x++) {
                if (map[y][x] === 0) {
                    floodFill(x, y);
                    reachable = true;
                    break;
                }
            }
            if (reachable) break;
        }
        return reachable;
    }

    function generateMap() {
        map.forEach(row => row.fill(1)); // Reset map to all walls

        createRoom(5, 5, 50, 50);
        createRoom(60, 60, 40, 40);
        createCorridor(30, 30, 70, 70);

        if (!isReachable()) {
            generateMap(); // Regenerate if not all areas are reachable
        }

        // Add spawn points and weapon pickups
        map[5][5] = 3; // Spawn point
        map[45][45] = 4; // Weapon pickup
    }

    function drawMap() {
        for (let y = 0; y < mapHeight; y++) {
            for (let x = 0; x < mapWidth; x++) {
                switch (map[y][x]) {
                    case 0:
                        ctx.fillStyle = 'gray';
                        break;
                    case 1:
                        ctx.fillStyle = 'black';
                        break;
                    case 3:
                        ctx.fillStyle = 'green';
                        break;
                    case 4:
                        ctx.fillStyle = 'red';
                        break;
                    default:
                        ctx.fillStyle = 'white';
                }
                ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
            }
        }
    }

    function addMinimapLegend() {
        const legendCanvas = document.createElement('canvas');
        legendCanvas.width = 100;
        legendCanvas.height = 50;
        const legendCtx = legendCanvas.getContext('2d');

        legendCtx.fillStyle = 'black';
        legendCtx.fillRect(0, 0, 20, 20);
        legendCtx.fillStyle = 'gray';
        legendCtx.fillRect(25, 0, 20, 20);
        legendCtx.fillStyle = 'green';
        legendCtx.fillRect(50, 0, 20, 20);
        legendCtx.fillStyle = 'red';
        legendCtx.fillRect(75, 0, 20, 20);

        document.body.appendChild(legendCanvas);
    }

    function addGenerateButton() {
        const button = document.createElement('button');
        button.textContent = 'Generate New Map';
        button.addEventListener('click', () => {
            generateMap();
            drawMap();
        });
        document.body.appendChild(button);
    }

    addMinimapLegend();
    addGenerateButton();

    generateMap();
    drawMap();
}
